package com.trampolim.api.education;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;import java.time.*;
import org.junit.jupiter.api.*;
import org.flywaydb.core.Flyway;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.support.JdbcTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.web.server.ResponseStatusException;

class InclusionPostgresTest {
    static JdbcTemplate jdbc,admin;static String schema;InclusionController inclusion;LearningAccess access;LearningController learning;AssessmentService assessments;TransactionTemplate tx;long student,teacher,manager;String studentEmail,teacherEmail,managerEmail;long course,module;
    @BeforeAll static void database(){String url=env("CAPACITA_DB_URL","jdbc:postgresql://localhost:5434/trampolim_capacita_db"),user=env("CAPACITA_DB_USERNAME","trampolim_capacita"),password=env("CAPACITA_DB_PASSWORD","dev_capacita_only");admin=new JdbcTemplate(new DriverManagerDataSource(url,user,password));schema="inclusion_test_"+UUID.randomUUID().toString().replace("-","");admin.execute("CREATE SCHEMA "+schema);var ds=new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema,user,password);Flyway.configure().dataSource(ds).locations("classpath:db/migration-capacita").load().migrate();jdbc=new JdbcTemplate(ds);}
    @AfterAll static void cleanup(){admin.execute("DROP SCHEMA "+schema+" CASCADE");}
    @BeforeEach void setup(){studentEmail=email();teacherEmail=email();managerEmail=email();student=account(studentEmail);teacher=account(teacherEmail);manager=account(managerEmail);jdbc.update("INSERT INTO learning_account_roles(user_id,role) VALUES (?,'TEACHER'),(?,'ADMIN')",teacher,manager);access=new LearningAccess(jdbc);ReflectionTestUtils.setField(access,"bootstrapAdmins","");inclusion=new InclusionController(jdbc,access);learning=new LearningController(jdbc,access);assessments=new AssessmentService(jdbc,access,learning);tx=new TransactionTemplate(new JdbcTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));course=((Number)learning.createCourse(teacherEmail,new LearningController.CourseInput("Inclusion fixture","","Math",null,"PUBLISHED")).get("id")).longValue();long subject=jdbc.queryForObject("INSERT INTO learning_subjects(course_id,title) VALUES (?,'Subject') RETURNING id",Long.class,course);module=jdbc.queryForObject("INSERT INTO learning_modules(subject_id,title) VALUES (?,'Module') RETURNING id",Long.class,subject);}
    private long account(String email){return jdbc.queryForObject("INSERT INTO student_users(email,password_hash,full_name,education_stage,email_verified,account_status,terms_accepted_at) VALUES (?,'test-only','Inclusion fixture','HIGH_SCHOOL',TRUE,'ACTIVE',CURRENT_TIMESTAMP) RETURNING id",Long.class,email);}
    @Test void preferencesAreValidatedPrivateAndPersisted(){assertEquals(false,inclusion.preferences(studentEmail).get("saved"));inclusion.preferences(studentEmail,new InclusionController.Preferences(150,true,true,true,1.5,true,true));var saved=(Map<?,?>)inclusion.preferences(studentEmail).get("preferences");assertEquals(150,((Number)saved.get("fontPercent")).intValue());assertEquals(true,saved.get("highContrast"));assertEquals(false,inclusion.preferences(teacherEmail).get("saved"));assertThrows(ResponseStatusException.class,()->inclusion.preferences(studentEmail,new InclusionController.Preferences(999,false,false,false,1,true,false)));assertThrows(ResponseStatusException.class,()->inclusion.preferences(studentEmail,new InclusionController.Preferences(100,false,false,false,50,true,false)));}
    @Test void supportIsPrivateConsentedAndIdempotent(){UUID key=UUID.randomUUID();assertThrows(ResponseStatusException.class,()->tx.execute(status->inclusion.request(studentEmail,new InclusionController.RequestInput(key,"Text alternative",false))));long id=((Number)tx.execute(status->inclusion.request(studentEmail,new InclusionController.RequestInput(key,"Text alternative",true))).get("id")).longValue();assertEquals(id,((Number)tx.execute(status->inclusion.request(studentEmail,new InclusionController.RequestInput(key,"Text alternative",true))).get("id")).longValue());assertEquals(1,inclusion.requests(studentEmail,false,null).size());assertTrue(inclusion.requests(teacherEmail,false,null).isEmpty());assertThrows(ResponseStatusException.class,()->inclusion.requests(teacherEmail,true,null));assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(status->inclusion.reply(studentEmail,id,new InclusionController.SupportReply("CLOSED","Reply"))));tx.executeWithoutResult(status->inclusion.reply(managerEmail,id,new InclusionController.SupportReply("IN_PROGRESS","A text resource is being prepared.")));assertEquals("IN_PROGRESS",inclusion.requests(studentEmail,false,null).get(0).get("status"));assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(status->inclusion.delete(teacherEmail,id)));tx.executeWithoutResult(status->inclusion.delete(studentEmail,id));assertTrue(inclusion.requests(studentEmail,false,null).isEmpty());}
    @Test void teacherExperienceRequiresIndependentAdministratorAndRevocableVerification(){var input=new InclusionController.TeacherVerification(teacherEmail,"Verified fixture experience","Private fixture evidence",true);assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(status->inclusion.verifyTeacher(teacherEmail,input)));assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(status->inclusion.verifyTeacher(managerEmail,new InclusionController.TeacherVerification(managerEmail,"Self","Self",true))));tx.executeWithoutResult(status->inclusion.verifyTeacher(managerEmail,input));var rows=inclusion.teachers(studentEmail);assertTrue(rows.stream().anyMatch(row->((Number)row.get("id")).longValue()==teacher));assertTrue(rows.stream().noneMatch(row->row.containsKey("verification_reference")||row.containsKey("email")));tx.executeWithoutResult(status->inclusion.verifyTeacher(managerEmail,new InclusionController.TeacherVerification(teacherEmail,"Revoked fixture","Private fixture evidence",false)));assertTrue(inclusion.teachers(studentEmail).stream().noneMatch(row->((Number)row.get("id")).longValue()==teacher));}
    @Test void authorizedExtensionChangesOnlyDeadline(){UUID q=UUID.randomUUID(),a=UUID.randomUUID(),b=UUID.randomUUID();var d=new AssessmentService.Definition("Expired fixture","","","",75,1,Instant.now().minusSeconds(60),false,true,true,List.of(new AssessmentService.Question(q,"MCQ","Pick A",1,List.of(new AssessmentService.Option(a,"A"),new AssessmentService.Option(b,"B")),a,"")),List.of());long id=((Number)tx.execute(status->assessments.create(teacherEmail,new AssessmentService.Input(course,null,module,"PUBLISHED",null,d))).get("id")).longValue();assertThrows(ResponseStatusException.class,()->tx.execute(status->assessments.start(studentEmail,id)));var extension=new AssessmentController.Accommodation(studentEmail,Instant.now().plusSeconds(3600));assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(status->assessments.accommodate(studentEmail,id,extension)));tx.executeWithoutResult(status->assessments.accommodate(teacherEmail,id,extension));UUID attempt=(UUID)tx.execute(status->assessments.start(studentEmail,id)).get("id");var result=tx.execute(status->assessments.submit(studentEmail,attempt,new AssessmentService.Submission(UUID.randomUUID(),Map.of(q.toString(),a.toString()))));assertEquals(true,result.get("passed"));var criteria=(Map<?,?>)result.get("criteria");assertEquals(75,criteria.get("passPercent"));assertEquals(1,criteria.get("maxAttempts"));assertTrue(Instant.parse(criteria.get("effectiveDueAt").toString()).isAfter(Instant.now()));assertThrows(ResponseStatusException.class,()->tx.execute(status->assessments.start(studentEmail,id)));}
    @Test void revokedJwtCannotMintNewPlaybackSession(){long lesson=jdbc.queryForObject("INSERT INTO learning_lessons(module_id,title,status,media_key,duration_seconds,validation_status) VALUES (?,'Video','PUBLISHED',?,180,'READY') RETURNING id",Long.class,module,UUID.randomUUID());var tokens=new com.trampolim.api.security.TrailTokenService();ReflectionTestUtils.setField(tokens,"capacitaSecret","inclusion-test-signing-secret-0123456789-abcdefghijklmnopqrstuvwxyz");String bearer="Bearer "+tokens.issue(com.trampolim.api.security.TrailTokenService.Trail.CAPACITA,studentEmail,student,0);var media=new LessonMediaController(jdbc,access,learning,new LessonMediaStore(),new JdbcTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));var playback=new LearningPlaybackController(jdbc,access,learning,media,tokens);assertNotNull(tx.execute(status->playback.start(studentEmail,lesson,false,bearer)));jdbc.update("UPDATE student_users SET token_version=1 WHERE id=?",student);assertThrows(ResponseStatusException.class,()->tx.execute(status->playback.start(studentEmail,lesson,false,bearer)));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM learning_playback_sessions WHERE student_id=?",Integer.class,student));}
    private static String email(){return UUID.randomUUID()+"@example.test";}private static String env(String name,String fallback){String value=System.getenv(name);return value==null||value.isBlank()?fallback:value;}
}
